 use sha2::{Digest, Sha256};
 use std::fs;
 use std::path::{Path, PathBuf};
+use std::sync::atomic::{AtomicU64, Ordering};

 use super::entry::CacheEntry;

+static TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);
+
+/// Write `data` to `path` atomically by writing to a uniquely-named sibling
+/// temp file first, then renaming. On the same filesystem `rename` is atomic
+/// on POSIX, so readers never see a partially-written file. The temp file name
+/// includes the PID and an incrementing counter to avoid collisions between
+/// concurrent threads and processes.
+fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
+    let seq = TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
+    let tmp_name = format!(".tmp.{}.{}", std::process::id(), seq,);
+    let tmp = path.with_extension(tmp_name);
+    fs::write(&tmp, data).with_context(|| format!("Failed to write temp file {:?}", tmp))?;
+    fs::rename(&tmp, path).with_context(|| {
+        let _ = fs::remove_file(&tmp);
+        format!("Failed to rename {:?} to {:?}", tmp, path)
+    })?;
+    Ok(())
+}
+
 /// Storage for cached templates.
 pub struct CacheStore {
     /// Root directory for cache.
